CREATE OR REPLACE FUNCTION mission_generic_owner.staff_phase_context_v1(p_session uuid,p_step text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
DECLARE q jsonb;data jsonb;
BEGIN
 IF p_session IS DISTINCT FROM '44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid THEN RETURN NULL;END IF;
 q:=mission_generic_owner.manual_staff_scope_v1(p_session);
 IF q IS NULL OR q->>'binding_sha256' IS DISTINCT FROM '61f8b90a41f1151aafc3a1407f264344797d0806bfbe07ab35f495b4ad62eafe'
 OR q#>>'{source_scope,definition_sha256}' IS DISTINCT FROM 'e481f0632468c133a47057c6fa640a5927e1cd427f20b378d3a3ce962dfe8477'
 THEN RETURN NULL;END IF;
 data:='{"schema_version":"c1266-phase-context/1","steps":{"inizio":{"actors":[{"actor_key":"png_1","goal_private":"Sostenere la versione davanti ai curiosi e rispondere alle domande senza rivelare subito il pagamento.","role_in_phase":"Portavoce della versione concordata","public_portrayal":"Parla ad alta voce, stringe la mascella quando gli chiedono chi gli abbia raccontato i fatti.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Nella versione concordata sostiene di aver ricevuto il racconto da qualcuno presente agli attacchi; in realtà non ha parlato con un testimone. Se gli chiedono che cosa abbia visto personalmente, ammette di non essere stato sul posto e insiste di averlo saputo da altri."},{"actor_key":"png_2","goal_private":"Sostenere la versione davanti ai curiosi e rispondere alle domande senza rivelare subito il pagamento.","role_in_phase":"Seconda voce che dipende dal racconto di Daichi","public_portrayal":"Esita, si volta verso Daichi prima di rispondere; corregge le attribuzioni su ciò che avrebbe visto.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Ha imparato la versione da ripetere insieme a Daichi e non ha parlato con alcun testimone. Se gli chiedono da chi abbia saputo degli attacchi, indica Daichi come propria fonte; se Daichi lo presenta come testimone, lo corregge: non era presente. Non conferma di aver visto ciò che non ha visto."}],"director_notes":"Rispondere alla domanda concreta del turno. Le richieste di fonti o di presenza personale aprono il confronto previsto da inizio_avanti: Daichi deve distinguere ciò che sostiene da ciò che ha visto, Keita può indicare Daichi come propria fonte. La reticenza sul pagamento non impedisce queste risposte. Nessuna confessione immediata, nessuna offensiva né spostamento PG in questa fase. Raccontare soltanto parole e comportamenti osservabili: nessuna spiegazione dei vincoli, delle intenzioni del prompt o di come il lettore debba interpretare la scena. Non riscrivere eventi pubblicati; le informazioni qui completate valgono per le risposte future."},"conclusione":{"actors":[{"actor_key":"png_1","goal_private":"Tentare di sostenere il racconto, ma rispondere su presenza personale e provenienza; lasciare emergere la contraddizione con l’altro giovane.","role_in_phase":"Portavoce della versione concordata","public_portrayal":"Parla ad alta voce, stringe la mascella quando gli chiedono chi gli abbia raccontato i fatti.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Nella versione concordata sostiene di aver ricevuto il racconto da qualcuno presente agli attacchi; in realtà non ha parlato con un testimone. Se gli chiedono che cosa abbia visto personalmente, ammette di non essere stato sul posto e insiste di averlo saputo da altri."},{"actor_key":"png_2","goal_private":"Tentare di sostenere il racconto, ma rispondere su presenza personale e provenienza; lasciare emergere la contraddizione con l’altro giovane.","role_in_phase":"Seconda voce che dipende dal racconto di Daichi","public_portrayal":"Esita, si volta verso Daichi prima di rispondere; corregge le attribuzioni su ciò che avrebbe visto.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Ha imparato la versione da ripetere insieme a Daichi e non ha parlato con alcun testimone. Se gli chiedono da chi abbia saputo degli attacchi, indica Daichi come propria fonte; se Daichi lo presenta come testimone, lo corregge: non era presente. Non conferma di aver visto ciò che non ha visto."}],"director_notes":"Fare emergere la differenza concreta fra le due risposte: Daichi richiama un presunto testimone, Keita conosce il racconto soltanto attraverso Daichi; nessuno era presente. Non ripetere una semplice evasione già pubblicata. Se i PG insistono sul motivo per cui diffondono una storia non osservata, Keita può lasciarsi sfuggire che dovevano ripetere quelle parole. Il pagamento non è una scoperta automatica dei PG: deve emergere da parole o comportamenti dei PNG. La scelta passaggio_5 richiede che il confronto abbia effettivamente smascherato il racconto o fatto emergere il compenso; una domanda generica da sola non basta. La Regia valuta questa condizione narrativa; il server verifica scelta, autorità e Combat, non la verità semantica della prosa. Raccontare soltanto parole e comportamenti osservabili: nessuna spiegazione dei vincoli, delle intenzioni del prompt o di come il lettore debba interpretare la scena. Non riscrivere eventi pubblicati; le informazioni qui completate valgono per le risposte future."},"fase_3":{"actors":[{"actor_key":"png_1","goal_private":"Sottrarsi alle domande con azioni comuni non letali, soltanto secondo intenzioni legali e conseguenze del server.","role_in_phase":"Portavoce della versione concordata","public_portrayal":"Parla ad alta voce, stringe la mascella quando gli chiedono chi gli abbia raccontato i fatti.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Nella versione concordata sostiene di aver ricevuto il racconto da qualcuno presente agli attacchi; in realtà non ha parlato con un testimone. Se gli chiedono che cosa abbia visto personalmente, ammette di non essere stato sul posto e insiste di averlo saputo da altri."},{"actor_key":"png_2","goal_private":"Sottrarsi alle domande con azioni comuni non letali, soltanto secondo intenzioni legali e conseguenze del server.","role_in_phase":"Seconda voce che dipende dal racconto di Daichi","public_portrayal":"Esita, si volta verso Daichi prima di rispondere; corregge le attribuzioni su ciò che avrebbe visto.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Ha imparato la versione da ripetere insieme a Daichi e non ha parlato con alcun testimone. Se gli chiedono da chi abbia saputo degli attacchi, indica Daichi come propria fonte; se Daichi lo presenta come testimone, lo corregge: non era presente. Non conferma di aver visto ciò che non ha visto."}],"director_notes":"Solo attacchi generici, movimento, parata e schivata consentiti. Nessuna tecnica né danno, difesa o scelta PG inventati. Il server determina neutralizzazione, resa e fine dello scontro; la prosa non anticipa gli esiti. Raccontare soltanto parole e comportamenti osservabili: nessuna spiegazione dei vincoli, delle intenzioni del prompt o di come il lettore debba interpretare la scena. Non riscrivere eventi pubblicati; le informazioni qui completate valgono per le risposte future."},"fase_4":{"actors":[{"actor_key":"png_1","goal_private":"Ammettere il compenso e riferire i dettagli della consegna anonima richiesti, distinguendoli dagli attacchi mai osservati.","role_in_phase":"Portavoce della versione concordata","public_portrayal":"Parla ad alta voce, stringe la mascella quando gli chiedono chi gli abbia raccontato i fatti.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Nella versione concordata sostiene di aver ricevuto il racconto da qualcuno presente agli attacchi; in realtà non ha parlato con un testimone. Se gli chiedono che cosa abbia visto personalmente, ammette di non essere stato sul posto e insiste di averlo saputo da altri."},{"actor_key":"png_2","goal_private":"Ammettere il compenso e riferire i dettagli della consegna anonima richiesti, distinguendoli dagli attacchi mai osservati.","role_in_phase":"Seconda voce che dipende dal racconto di Daichi","public_portrayal":"Esita, si volta verso Daichi prima di rispondere; corregge le attribuzioni su ciò che avrebbe visto.","known_facts_private":"Le accuse sugli attacchi sono inventate; non ha assistito agli attacchi e non conosce i loro veri responsabili né il mandante. Sa che entrambi hanno accettato un compenso per ripetere una versione concordata. Il pagamento anonimo è stato ritirato la sera precedente, alla chiusura del mercato, sotto un banco vuoto dietro le botteghe: una busta con monete e un foglio con le frasi da ripetere. Non ha incontrato chi ha lasciato la busta. Nessun nome, simbolo, volto o segno identificativo disponibile. Ha imparato la versione da ripetere insieme a Daichi e non ha parlato con alcun testimone. Se gli chiedono da chi abbia saputo degli attacchi, indica Daichi come propria fonte; se Daichi lo presenta come testimone, lo corregge: non era presente. Non conferma di aver visto ciò che non ha visto."}],"director_notes":"Rispondere alle domande su dove, quando e come: sera precedente, chiusura del mercato, banco vuoto dietro le botteghe, busta con monete e foglio. Ammettere di non aver visto il depositante e di non conoscere il mandante. Non inventare identificativi. Riutilizzare questi stessi fatti nei turni successivi, senza cambiare versione della consegna. Raccontare soltanto parole e comportamenti osservabili: nessuna spiegazione dei vincoli, delle intenzioni del prompt o di come il lettore debba interpretare la scena. Non riscrivere eventi pubblicati; le informazioni qui completate valgono per le risposte future."}},"routes":{"inizio":{"trigger_key":"avanti","transition_key":"inizio_avanti","destination_step_key":"conclusione","scope":"world_event"},"conclusione":{"trigger_key":"passaggio_5","transition_key":"conclusione_passaggio_5","destination_step_key":"fase_3","scope":"combat_entry"}}}'::jsonb;
 IF NOT (data->'steps' ? p_step) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('director',data->'steps'->p_step,'route',data->'routes'->p_step);
END $function$;
REVOKE ALL ON FUNCTION mission_generic_owner.staff_phase_context_v1(uuid,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION mission_creation_owner.director_context(p_session uuid, p_step text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b mission_generic_owner.run_bindings;c jsonb;e jsonb;s jsonb;phase jsonb;
begin
 select * into b from mission_generic_owner.run_bindings where master_session_id=p_session;
 if not found or not(b.snapshot?'creation') then return null;end if;
 c:=b.snapshot->'creation';
 if b.snapshot_sha256<>mission_internal.fingerprint(b.snapshot) or b.snapshot->>'creation_sha256'<>mission_internal.fingerprint(c)
 or c->>'document_sha256'<>mission_internal.fingerprint(c->'document') then raise exception 'MC_CONTEXT_DRIFT' using errcode='40001';end if;
 if not exists(select 1 from jsonb_array_elements(b.snapshot#>'{definition,scenes}') x where x->>'step_key'=p_step)
 then raise exception 'MC_CONTEXT_STEP_SCOPE' using errcode='22023';end if;
 e:=c#>'{document,editorial}';select x into s from jsonb_array_elements(e->'scenes') x where x->>'step_key'=p_step;
 phase:=mission_generic_owner.staff_phase_context_v1(p_session,p_step);
 IF phase IS NOT NULL THEN s:=s||(phase->'director');END IF;
 return jsonb_build_object('schema_version','mission-director-context/1','setting',jsonb_build_object(
 'name',coalesce(nullif(btrim(s#>>'{setting,name}'),''),e#>>'{setting,name}',''),
 'description',coalesce(nullif(btrim(s#>>'{setting,description}'),''),e#>>'{setting,description}','')),
 'plot_private',coalesce(e->>'plot_private',''),'director_notes',coalesce(s->>'director_notes',''),
 'entry_public',coalesce(s->>'entry_public',''),'actors',coalesce(s->'actors','[]'::jsonb),'consequences',coalesce(s->'consequences','[]'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION mission_generic_owner.manual_staff_effect_v1(p_session uuid, p_step text, p_op jsonb, p_roster jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q jsonb;sc jsonb;trig jsonb;dest text;kind text;scope text;users jsonb;intents jsonb;plan uuid;terminal boolean;trigger_name text;phase jsonb;route jsonb;
BEGIN
 q:=mission_generic_owner.manual_staff_scope_v1(p_session);
 IF q IS NULL OR p_roster->>'master_session_id' IS DISTINCT FROM p_session::text THEN RETURN NULL;END IF;
 SELECT plan_version_id INTO plan FROM public.mission_run_state WHERE master_session_id=p_session;
 sc:=mission_generic_owner.scene(p_session,p_step);kind:=p_op->>'source_kind';trigger_name:=p_op->>'trigger_key';
 IF kind='player_choice' THEN
  phase:=mission_generic_owner.staff_phase_context_v1(p_session,p_step);route:=phase->'route';
  IF route IS NULL OR route='null'::jsonb OR trigger_name IS DISTINCT FROM route->>'trigger_key' THEN RETURN NULL;END IF;
  SELECT value INTO trig FROM jsonb_array_elements(sc->'triggers')
   WHERE value->>'trigger_key'=trigger_name AND value->>'source_kind'=kind AND value->>'transition_key'=route->>'transition_key';
  IF trig IS NULL THEN RETURN NULL;END IF;
  SELECT to_step_key INTO dest FROM public.mission_plan_transitions WHERE plan_version_id=plan AND from_step_key=p_step AND transition_key=trig->>'transition_key';
  IF dest IS NULL OR dest IS DISTINCT FROM route->>'destination_step_key'
   OR p_op#>>'{destination_context,step_key}' IS DISTINCT FROM dest
   OR p_op->>'action_kind' IS DISTINCT FROM trigger_name THEN RETURN NULL;END IF;
  scope:=route->>'scope';
  IF scope='world_event' THEN
   IF p_op->>'encounter_key' IS NOT NULL OR jsonb_array_length(mission_generic_owner.scene(p_session,dest)->'encounters')<>0 THEN RETURN NULL;END IF;
  ELSIF scope='combat_entry' THEN
   IF p_op->>'encounter_key' IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(mission_generic_owner.scene(p_session,dest)->'encounters') e WHERE e->>'encounter_key'=p_op->>'encounter_key') THEN RETURN NULL;END IF;
  ELSE RETURN NULL;END IF;
  dest:=NULL;
 ELSIF kind='narrative_event' THEN
  SELECT value INTO trig FROM jsonb_array_elements(sc->'triggers') WHERE value->>'trigger_key'=p_op->>'trigger_key' AND value->>'source_kind'=kind;
  IF trig IS NULL THEN RETURN NULL;END IF;
  SELECT to_step_key INTO dest FROM public.mission_plan_transitions WHERE plan_version_id=plan AND from_step_key=p_step AND transition_key=trig->>'transition_key';
  IF dest IS NULL OR p_op#>>'{destination_context,step_key}' IS DISTINCT FROM dest THEN RETURN NULL;END IF;
  SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(mission_generic_owner.run_plan_settings(p_session)->'terminal_steps') term WHERE term->>'step_key'=dest) INTO terminal;
  IF p_op->>'encounter_key' IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(mission_generic_owner.scene(p_session,dest)->'encounters') e WHERE e->>'encounter_key'=p_op->>'encounter_key') THEN RETURN NULL;END IF;
   scope:='combat_entry';dest:=NULL;
  ELSIF terminal THEN scope:='world_event';dest:=NULL;
  ELSE scope:='collective_transition';END IF;
 ELSIF kind IS NULL AND p_op->>'action_kind'='conflict' AND p_op->>'trigger_key' IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sc->'encounters') e WHERE e->>'encounter_key'=p_op->>'encounter_key') THEN RETURN NULL;END IF;
  scope:='combat_entry';dest:=NULL;kind:='encounter';trigger_name:=p_op->>'encounter_key';
 ELSE RETURN NULL;END IF;
 SELECT jsonb_agg(value->'user_id' ORDER BY value->>'user_id') INTO users FROM jsonb_array_elements(p_roster->'participants');
 IF jsonb_array_length(users) IS DISTINCT FROM (q#>>'{source_scope,PG_count}')::integer
 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(users) u WHERE NOT(q->'actor_user_ids' ? u.value)) THEN RETURN NULL;END IF;
 intents:=CASE WHEN kind='player_choice' THEN '["interact"]'::jsonb WHEN scope='collective_transition' THEN '["move","accompany"]'::jsonb WHEN scope='world_event' THEN '["observe","interact","cease","wait","other"]'::jsonb ELSE '["observe","move","accompany","interact","attack","cease","wait","other"]'::jsonb END;
 RETURN jsonb_build_object('schema_version','mission-opportunity-effect/1','scope',scope,'affected_pg_user_ids',CASE WHEN scope='collective_transition' THEN users ELSE '[]'::jsonb END,'destination_step_key',dest,'eligible_initiator_user_ids',users,'allowed_initiator_intents',intents,'source_kind',kind,'trigger_key',trigger_name);
END $function$


CREATE OR REPLACE FUNCTION mission_generic_owner.c1266_role_decision_v2(p_work uuid, p_decision jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_decision#>>'{role_interpretation,schema_version}'='mission-role-interpretation/4' THEN
 DECLARE w mission_generic_owner.work_items;r jsonb;interp jsonb;op jsonb;policy jsonb;original jsonb;effective jsonb;disposition jsonb;
 item jsonb;row_node jsonb;atom jsonb;idx integer;reason text:='none';has_move boolean;initiated boolean:=false;peer boolean;projection jsonb;effect text;
BEGIN
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT mission_generic_owner.c1266_role_keys_v1(p_decision,ARRAY['schema_version','source_window_id','source_role_ids','source_evidence','opportunity_id','action_kind','entry_side','world_reaction_intent','npc_intents','role_interpretation'])
  OR p_decision->>'schema_version' IS DISTINCT FROM 'mission-director-proposal/4'
  OR p_decision->>'source_window_id' IS DISTINCT FROM w.authority_receipt_id::text
 THEN RAISE EXCEPTION 'C1266_ROLE_PROPOSAL_SHAPE';END IF;
 interp:=p_decision->'role_interpretation';r:=w.payload->'role_roster';peer:=interp->>'schema_version'='mission-role-interpretation/4' AND w.payload#>>'{peer_confirmation,schema_version}'='mission-peer-confirmation-contract/2';
 IF (w.payload ? 'peer_confirmation') IS DISTINCT FROM peer THEN RAISE EXCEPTION 'C1266_PEER_INTERPRETATION_VERSION_REQUIRED';END IF;
 PERFORM mission_generic_owner.c1266_role_interpretation_assert_v2(w.id,interp);
 projection:=mission_generic_owner.c1266_role_current_projection_v2(w.id,interp);
 original:=jsonb_set(p_decision-'role_interpretation','{schema_version}','"mission-director-proposal/2"'::jsonb);
 effective:=original;
 IF p_decision->>'opportunity_id' IS NOT NULL THEN
  SELECT candidate INTO STRICT op FROM jsonb_array_elements(w.payload->'opportunities') candidate
   WHERE candidate->>'opportunity_id'=p_decision->>'opportunity_id';
  policy:=CASE WHEN EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) THEN mission_generic_owner.manual_staff_effect_v1(w.master_session_id,w.step_key,op,r) ELSE mission_generic_owner.c1266_role_effect_v1(w.step_key,op,r) END;
  IF policy IS NULL OR policy IS DISTINCT FROM op->'effect_policy' THEN reason:='effect_policy_not_supported';
  ELSIF policy->>'scope'='collective_transition' THEN
   FOR idx IN 0..jsonb_array_length(r->'participants')-1 LOOP
    row_node:=r->'participants'->idx;item:=interp->'interpretations'->idx;has_move:=false;
    IF row_node->>'role_status'<>'valid' THEN reason:='collective_coverage_missing';EXIT;END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(item->'intents') unknown_atom WHERE unknown_atom#>>'{temporal,timing}'='unresolved') THEN reason:='required_destination_unresolved';EXIT;END IF;
    FOR atom IN SELECT value FROM jsonb_array_elements(item->'intents') WHERE value#>>'{temporal,timing}'='now' OR(value#>>'{temporal,timing}'='after' AND value#>>'{temporal,prerequisite}'='immediate_sequence') OR(peer AND value#>>'{temporal,timing}'='if' AND value#>>'{temporal,prerequisite}'='peer_confirmed') LOOP
     IF atom->>'intent' IN('move','accompany') THEN
      IF atom#>>'{destination,kind}'='undetermined' THEN reason:='required_destination_unresolved';EXIT;END IF;
      IF atom#>>'{destination,step_key}' IS DISTINCT FROM policy->>'destination_step_key' THEN reason:='incompatible_pg_intents';EXIT;END IF;
      has_move:=true;
     ELSIF atom->>'intent' IN('attack','defend','wait') THEN reason:='incompatible_pg_intents';EXIT;
     ELSIF atom->>'intent'='cease' AND atom#>>'{destination,kind}'='canonical' THEN reason:='incompatible_pg_intents';EXIT;
     END IF;
    END LOOP;
    IF reason<>'none' THEN EXIT;END IF;
    IF NOT has_move THEN reason:=CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(item->'intents') a WHERE a->>'intent'='undetermined')
      THEN 'required_destination_unresolved' ELSE 'incompatible_pg_intents' END;EXIT;END IF;
   END LOOP;
  ELSIF policy->>'scope'='world_event' THEN
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai
     WHERE ri->>'role_id' IS NOT NULL AND ((ai#>>'{temporal,timing}'='now' AND ai->>'intent' IN('attack','defend')) OR(ai#>>'{temporal,timing}'='unresolved' AND ai->>'intent' IN('attack','defend','undetermined') AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') verified_row WHERE verified_row->>'user_id'=ri->>'user_id' AND verified_row->>'role_status'='valid'))))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_decision->'npc_intents') ni WHERE ni->>'entry_kind'='offense')
    OR EXISTS(SELECT 1 FROM public.combat_v2_sessions cs WHERE cs.master_session_id=w.master_session_id AND cs.closed_at IS NULL)
   THEN reason:='incompatible_pg_intents';END IF;
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai
    WHERE ai#>>'{temporal,timing}'='now' AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') verified_row WHERE verified_row->>'user_id'=ri->>'user_id' AND verified_row->>'role_status'='valid') AND policy->'eligible_initiator_user_ids' ? (ri->>'user_id') AND policy->'allowed_initiator_intents' ? (ai->>'intent')) INTO initiated;
   IF reason='none' AND NOT initiated THEN reason:='required_destination_unresolved';END IF;
  ELSIF policy->>'scope'='combat_entry' THEN
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') valid_ri JOIN LATERAL jsonb_array_elements(valid_ri->'intents') unknown_ai ON true JOIN LATERAL jsonb_array_elements(r->'participants') valid_r ON valid_r->>'user_id'=valid_ri->>'user_id' WHERE valid_r->>'role_status'='valid' AND unknown_ai#>>'{temporal,timing}'='unresolved' AND unknown_ai->>'intent' IN('attack','defend','undetermined')) THEN reason:='required_destination_unresolved';END IF;
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai
    WHERE ai#>>'{temporal,timing}'='now' AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') verified_row WHERE verified_row->>'user_id'=ri->>'user_id' AND verified_row->>'role_status'='valid') AND policy->'eligible_initiator_user_ids' ? (ri->>'user_id') AND policy->'allowed_initiator_intents' ? (ai->>'intent')) INTO initiated;
   IF NOT initiated AND NOT(p_decision->>'entry_side'='png' AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_decision->'npc_intents') ni WHERE ni->>'entry_kind'='offense'))
   THEN reason:='required_destination_unresolved';END IF;
  ELSE reason:='effect_policy_not_supported';END IF;
 END IF;
 -- A player_choice is attested by the first quoted role at publication, not an unrelated observer.
 IF reason='none' AND op->>'source_kind'='player_choice'
  AND mission_generic_owner.staff_phase_context_v1(w.master_session_id,w.step_key) IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') rr
   JOIN LATERAL jsonb_array_elements(interp->'interpretations') ri ON ri->>'user_id'=rr->>'user_id' AND ri->>'role_id'=rr->>'role_id'
   JOIN LATERAL jsonb_array_elements(ri->'intents') ai ON true
   WHERE rr->>'role_status'='valid' AND rr->>'role_id'=p_decision#>>'{source_evidence,0,role_id}'
    AND ai->>'intent'='interact' AND ai#>>'{temporal,timing}'='now')
 THEN reason:='incompatible_pg_intents';END IF;
 IF peer AND EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai WHERE ai#>>'{temporal,prerequisite}'='peer_confirmed') AND (policy->>'scope') IS DISTINCT FROM 'collective_transition' THEN reason:='incompatible_pg_intents';END IF;
 IF reason<>'none' THEN
  effective:=original||jsonb_build_object('opportunity_id',null,'action_kind','context','entry_side',null,'npc_intents','[]'::jsonb,
   'world_reaction_intent','Presentare soltanto fatti pubblici correnti e tentativi individuali distinti ancora irrisolti. Nessuna transizione o esito dei tentativi è attestato. Non inventare ostacoli, arresti, interventi PNG o divisioni del gruppo. Non imporre che nessuno prosegua.');
 END IF;
 effect:=CASE WHEN reason='none' AND effective->>'opportunity_id' IS NOT NULL THEN policy->>'scope' ELSE 'context' END;
 IF effect IS NULL OR effect NOT IN('context','collective_transition','world_event','combat_entry') THEN RAISE EXCEPTION 'C1266_PEER4_EFFECT_INVALID';END IF;
 disposition:=jsonb_build_object('schema_version',(CASE WHEN peer THEN 'mission-role-disposition/4' ELSE 'mission-role-disposition/2' END),'source_window_id',w.authority_receipt_id,
  'source_revision',r->>'source_revision','decision_work_id',w.id,'proposed_opportunity_id',p_decision->'opportunity_id',
  'effective_opportunity_id',effective->'opportunity_id','status',CASE WHEN reason='none' THEN 'allowed' ELSE 'context_fallback' END,
  'reason',reason,'effect',effect,'interpretation_sha256',public.combat_v2_sha256(interp),'temporal_contract_sha256',(CASE WHEN peer THEN '0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8' ELSE '64adc5a2eec27bc4ac02ffa3d9f8afd485f3a1f9ea4879b9ccfe1c3bb5b32cc2' END),
 'current_projection_sha256',public.combat_v2_sha256(projection));
 RETURN jsonb_build_object('original_core_decision',original,'effective_core_decision',effective,'role_interpretation',interp,'role_disposition',disposition,'current_projection',projection,
  'stored_decision',jsonb_set(effective,'{schema_version}','"mission-director-proposal/4"'::jsonb)||jsonb_build_object('role_interpretation',interp,'role_disposition',disposition,'current_projection',projection));
END;
 END IF;
 DECLARE w mission_generic_owner.work_items;r jsonb;interp jsonb;op jsonb;policy jsonb;original jsonb;effective jsonb;disposition jsonb;
 item jsonb;row_node jsonb;atom jsonb;idx integer;reason text:='none';has_move boolean;initiated boolean:=false;peer boolean;
BEGIN
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT mission_generic_owner.c1266_role_keys_v1(p_decision,ARRAY['schema_version','source_window_id','source_role_ids','source_evidence','opportunity_id','action_kind','entry_side','world_reaction_intent','npc_intents','role_interpretation'])
  OR p_decision->>'schema_version' IS DISTINCT FROM 'mission-director-proposal/4'
  OR p_decision->>'source_window_id' IS DISTINCT FROM w.authority_receipt_id::text
 THEN RAISE EXCEPTION 'C1266_ROLE_PROPOSAL_SHAPE';END IF;
 interp:=p_decision->'role_interpretation';r:=w.payload->'role_roster';peer:=interp->>'schema_version'='mission-role-interpretation/3' AND w.payload#>>'{peer_confirmation,schema_version}'='mission-peer-confirmation-contract/1';
 IF (w.payload ? 'peer_confirmation') IS DISTINCT FROM peer THEN RAISE EXCEPTION 'C1266_PEER_INTERPRETATION_VERSION_REQUIRED';END IF;
 PERFORM mission_generic_owner.c1266_role_interpretation_assert_v2(w.id,interp);
 original:=jsonb_set(p_decision-'role_interpretation','{schema_version}','"mission-director-proposal/2"'::jsonb);
 effective:=original;
 IF p_decision->>'opportunity_id' IS NOT NULL THEN
  SELECT candidate INTO STRICT op FROM jsonb_array_elements(w.payload->'opportunities') candidate
   WHERE candidate->>'opportunity_id'=p_decision->>'opportunity_id';
  policy:=CASE WHEN EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) THEN mission_generic_owner.manual_staff_effect_v1(w.master_session_id,w.step_key,op,r) ELSE mission_generic_owner.c1266_role_effect_v1(w.step_key,op,r) END;
  IF policy IS NULL OR policy IS DISTINCT FROM op->'effect_policy' THEN reason:='effect_policy_not_supported';
  ELSIF policy->>'scope'='collective_transition' THEN
   FOR idx IN 0..jsonb_array_length(r->'participants')-1 LOOP
    row_node:=r->'participants'->idx;item:=interp->'interpretations'->idx;has_move:=false;
    IF row_node->>'role_status'<>'valid' THEN reason:='collective_coverage_missing';EXIT;END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(item->'intents') unknown_atom WHERE unknown_atom#>>'{temporal,timing}'='unresolved') THEN reason:='required_destination_unresolved';EXIT;END IF;
    FOR atom IN SELECT value FROM jsonb_array_elements(item->'intents') WHERE value#>>'{temporal,timing}'='now' OR(peer AND value#>>'{temporal,timing}'='if' AND value#>>'{temporal,prerequisite}'='peer_confirmed') LOOP
     IF atom->>'intent' IN('move','accompany') THEN
      IF atom#>>'{destination,kind}'='undetermined' THEN reason:='required_destination_unresolved';EXIT;END IF;
      IF atom#>>'{destination,step_key}' IS DISTINCT FROM policy->>'destination_step_key' THEN reason:='incompatible_pg_intents';EXIT;END IF;
      has_move:=true;
     ELSIF atom->>'intent' IN('attack','defend','wait') THEN reason:='incompatible_pg_intents';EXIT;
     ELSIF atom->>'intent'='cease' AND atom#>>'{destination,kind}'='canonical' THEN reason:='incompatible_pg_intents';EXIT;
     END IF;
    END LOOP;
    IF reason<>'none' THEN EXIT;END IF;
    IF NOT has_move THEN reason:=CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(item->'intents') a WHERE a->>'intent'='undetermined')
      THEN 'required_destination_unresolved' ELSE 'incompatible_pg_intents' END;EXIT;END IF;
   END LOOP;
  ELSIF policy->>'scope'='world_event' THEN
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai
     WHERE ri->>'role_id' IS NOT NULL AND ((ai#>>'{temporal,timing}'='now' AND ai->>'intent' IN('attack','defend')) OR(ai#>>'{temporal,timing}'='unresolved' AND ai->>'intent' IN('attack','defend','undetermined') AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') verified_row WHERE verified_row->>'user_id'=ri->>'user_id' AND verified_row->>'role_status'='valid'))))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_decision->'npc_intents') ni WHERE ni->>'entry_kind'='offense')
    OR EXISTS(SELECT 1 FROM public.combat_v2_sessions cs WHERE cs.master_session_id=w.master_session_id AND cs.closed_at IS NULL)
   THEN reason:='incompatible_pg_intents';END IF;
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai
    WHERE ai#>>'{temporal,timing}'='now' AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') verified_row WHERE verified_row->>'user_id'=ri->>'user_id' AND verified_row->>'role_status'='valid') AND policy->'eligible_initiator_user_ids' ? (ri->>'user_id') AND policy->'allowed_initiator_intents' ? (ai->>'intent')) INTO initiated;
   IF reason='none' AND NOT initiated THEN reason:='required_destination_unresolved';END IF;
  ELSIF policy->>'scope'='combat_entry' THEN
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') valid_ri JOIN LATERAL jsonb_array_elements(valid_ri->'intents') unknown_ai ON true JOIN LATERAL jsonb_array_elements(r->'participants') valid_r ON valid_r->>'user_id'=valid_ri->>'user_id' WHERE valid_r->>'role_status'='valid' AND unknown_ai#>>'{temporal,timing}'='unresolved' AND unknown_ai->>'intent' IN('attack','defend','undetermined')) THEN reason:='required_destination_unresolved';END IF;
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai
    WHERE ai#>>'{temporal,timing}'='now' AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') verified_row WHERE verified_row->>'user_id'=ri->>'user_id' AND verified_row->>'role_status'='valid') AND policy->'eligible_initiator_user_ids' ? (ri->>'user_id') AND policy->'allowed_initiator_intents' ? (ai->>'intent')) INTO initiated;
   IF NOT initiated AND NOT(p_decision->>'entry_side'='png' AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_decision->'npc_intents') ni WHERE ni->>'entry_kind'='offense'))
   THEN reason:='required_destination_unresolved';END IF;
  ELSE reason:='effect_policy_not_supported';END IF;
 END IF;
 -- A player_choice is attested by the first quoted role at publication, not an unrelated observer.
 IF reason='none' AND op->>'source_kind'='player_choice'
  AND mission_generic_owner.staff_phase_context_v1(w.master_session_id,w.step_key) IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'participants') rr
   JOIN LATERAL jsonb_array_elements(interp->'interpretations') ri ON ri->>'user_id'=rr->>'user_id' AND ri->>'role_id'=rr->>'role_id'
   JOIN LATERAL jsonb_array_elements(ri->'intents') ai ON true
   WHERE rr->>'role_status'='valid' AND rr->>'role_id'=p_decision#>>'{source_evidence,0,role_id}'
    AND ai->>'intent'='interact' AND ai#>>'{temporal,timing}'='now')
 THEN reason:='incompatible_pg_intents';END IF;
 IF peer AND EXISTS(SELECT 1 FROM jsonb_array_elements(interp->'interpretations') ri CROSS JOIN LATERAL jsonb_array_elements(ri->'intents') ai WHERE ai#>>'{temporal,prerequisite}'='peer_confirmed') AND (policy->>'scope') IS DISTINCT FROM 'collective_transition' THEN reason:='incompatible_pg_intents';END IF;
 IF reason<>'none' THEN
  effective:=original||jsonb_build_object('opportunity_id',null,'action_kind','context','entry_side',null,'npc_intents','[]'::jsonb,
   'world_reaction_intent','Presentare soltanto fatti pubblici correnti e tentativi individuali distinti ancora irrisolti. Nessuna transizione o esito dei tentativi è attestato. Non inventare ostacoli, arresti, interventi PNG o divisioni del gruppo. Non imporre che nessuno prosegua.');
 END IF;
 disposition:=jsonb_build_object('schema_version',(CASE WHEN peer THEN 'mission-role-disposition/3' ELSE 'mission-role-disposition/2' END),'source_window_id',w.authority_receipt_id,
  'source_revision',r->>'source_revision','decision_work_id',w.id,'proposed_opportunity_id',p_decision->'opportunity_id',
  'effective_opportunity_id',effective->'opportunity_id','status',CASE WHEN reason='none' THEN 'allowed' ELSE 'context_fallback' END,
  'reason',reason,'interpretation_sha256',public.combat_v2_sha256(interp),'temporal_contract_sha256',(CASE WHEN peer THEN '3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda' ELSE '64adc5a2eec27bc4ac02ffa3d9f8afd485f3a1f9ea4879b9ccfe1c3bb5b32cc2' END),
 'current_projection_sha256',public.combat_v2_sha256(mission_generic_owner.c1266_role_current_projection_v2(w.id,interp)));
 RETURN jsonb_build_object('original_core_decision',original,'effective_core_decision',effective,'role_interpretation',interp,'role_disposition',disposition,
  'stored_decision',jsonb_set(effective,'{schema_version}','"mission-director-proposal/4"'::jsonb)||jsonb_build_object('role_interpretation',interp,'role_disposition',disposition));
END;
END
