   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(interp->''interpretations'') ri CROSS JOIN LATERAL jsonb_array_elements(ri->''intents'') ai
    WHERE ai#>>''{temporal,timing}''=''now'' AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->''participants'') verified_row WHERE verified_row->>''user_id''=ri->>''user_id'' AND verified_row->>''role_status''=''valid'') AND policy->''eligible_initiator_user_ids'' ? (ri->>''user_id'') AND policy->''allowed_initiator_intents'' ? (ai->>''intent'')) INTO initiated;
