 IF (md5((SELECT prosrc FROM pg_proc WHERE oid=to_regprocedure('mission_creation_owner.director_context(uuid,text)')))='79172bfb759b311121fb1647e5e4aa1a') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'PHASE_RECOVERY_SOURCE_DRIFT' USING ERRCODE='40001';END IF;
